Translate("ptBR", "excavation-site", {
	title = "Excavation Site",
	aliases = { "Excavation Site: Wetlands" },
	sections = {
		{
			title = "Resumo",
			text = [=[No alto das colinas do {link:wetlands}Pantanal{/link}, acima do acampamento arruinado da escavação de {link:prospector-whelgar}Whelgar{/link}, há um lugar que parece ter sido deixado para trás pelo tempo. Há algum tempo, uma névoa estranha desce das montanhas ali, e luzes brilham nas alturas durante a noite. Um segundo acampamento se ergue entre as rochas, com tendas, caixotes e enormes crânios com chifres meio enterrados no chão, e uma grande pedra verde atrás de uma barricada de madeira. Mais além, sob uma árvore alta, uma coluna de névoa azul se abre para dentro da terra. O que espera lá embaixo é mais antigo que qualquer fortaleza anã.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra quem fez os lugares antigos sob as terras altas, nem quando. Os escavadores da {link:explorers-league}Liga dos Exploradores{/link} no pântano abaixo encontraram ossos enormes e uma tábua escrita na língua dos titãs, a {link:goaz-stone}Goaz Stone{/link}, que fala de Deuses Antigos acorrentados sob a terra. Se a tábua e as câmaras das terras altas fazem parte de uma mesma história, nenhum estudioso ainda soube dizer. O que se sabe é que os construtos dos titãs despertaram aqui, e que se desviaram de seu propósito.]=],
		},
		{
			title = "A Descida",
			text = [=[O caminho para baixo passa por quatro lugares que os escavadores nomearam. O Lost Dig Site é o que resta de um acampamento que cavou fundo demais. O Stalker's Thicket é um emaranhado de vegetação onde raptores caçam em bandos. O Lost Marsh é uma caverna alagada de juncos e água negra, onde crânios gigantes jazem entre os caniços e crocoliscos deslizam sob a superfície. No fim fica o Site of the Guardian, uma câmara de grandes pedras lavradas.]=],
		},
		{
			title = "Os que Habitam Embaixo",
			text = [=[• {b}{link:saltspine}Saltspine{/link}{/b}, um crocolisco pálido de grande idade e tamanho.
• {b}{link:shadetooth}Shadetooth{/link}{/b}, um raptor maior que qualquer um do pântano acima, com um bando de caça próprio.
• {b}O {link:highland-horror}Highland Horror{/link}{/b}, uma coisa monstruosa de lama e podridão que se ergue do brejo.
• {b}O {link:relic-guardian}Relic Guardian{/link}{/b}, um construto de pedra cinzenta que ainda guarda a câmara que foi feito para guardar.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[A {link:explorers-league}Liga dos Exploradores{/link} tem bons motivos para se interessar pelo que quer que esteja lá embaixo. Seus colegas na escavação de {link:prospector-whelgar}Whelgar{/link} já pagaram caro pelos segredos do {link:wetlands}Pantanal{/link}, e os sobreviventes ainda estão presos em seu penhasco. As criaturas das terras altas, tartarugas, aranhas e feras à espreita, tornaram-se ousadas ao redor do portal.]=],
		},
	},
})

